256	// A pack's skill-owned checks: any <pack>/skills/<skill>/checks.mjs (default
257	// export = an array of coded rules) plus its declared-checks.json (the same
258	// declaration format a pack's own carries). Isolated per skill; run gated by the
259	// owning pack being active, exactly like the pack's own rules — a skill is pack
260	// content, so its checks ride the pack's activation.
261	async function scanSkillChecks(packDir, errors) {
262	  const rules = [];
263	  const skillsRoot = join(packDir, 'skills');
264	  if (!existsSync(skillsRoot)) return rules;
265	  let names;
266	  try {
267	    names = readdirSync(skillsRoot, { withFileTypes: true })
268	      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
269	  } catch (e) {
270	    errors.push({ what: `${LOCAL_PACKS_SUBDIR} skills path is not a readable directory: ${e.message}`, fix: 'make the pack\'s skills/ a directory (or remove it)', dir: skillsRoot });
271	    return rules;
272	  }
273	  for (const name of names) {
274	    const skillDir = join(skillsRoot, name);
275	    rules.push(...await declaredChecksIn(skillDir, `the ${name} skill`, errors));
276	    const manifest = join(skillDir, 'checks.mjs');
277	    if (!existsSync(manifest)) continue;
278	    try {
279	      rules.push(...(await import(pathToFileURL(manifest).href)).default);
280	    } catch (e) {
281	      errors.push({ what: `local skill check ${name}/checks.mjs failed to load: ${e.message}`, fix: 'fix or remove the skill\'s checks.mjs', dir: skillDir });
282	    }
283	  }
284	  return rules;
285	}
