26	
27	const args = process.argv.slice(2);
28	const has = (flag) => args.includes(flag);
29	const value = (flag) => (args.includes(flag) ? args[args.indexOf(flag) + 1] : null);
30	// The repo to sweep. `--root` first, then CLAUDE_PROJECT_DIR, and only then the cwd.
31	// The env var is not a convenience: the callers that run this from inside a converge
32	// (the update runner) have a cwd that no longer exists — the vendor step deletes
33	// `.claudinite/shared/`, which is where code-work's cwd lives — and `process.cwd()` then
34	// throws `ENOENT … uv_cwd` before a single check runs, which reads from the outside as
35	// "this mount has no checks" (#689). engine/selftest.mjs has always resolved its root
36	// this way; this closes the disagreement for every caller, not just that one.
37	const root = value('--root') || process.env.CLAUDE_PROJECT_DIR || process.cwd();
38	
39	if (has('--list')) {
40	  const { packs } = await discoverPacks({ localRoot: root });
41	  for (const r of packRules(packs)) {
42	    // A declared check carries neither a description nor a doc pointer — it
43	    // states its own case — so the catalog prints its failure message in that
44	    // column and leaves the pointer empty.
45	    console.log(`${r.id}\t${r.severity}\t${r.description ?? r.why ?? ''}\t${r.doc ?? ''}`);
46	  }
47	  process.exit(0);
48	}
49	
50	if (has('--init')) {
51	  const { seedDeclaration } = await import('./helpers/seed-declaration.mjs');
52	  const { packs } = await discoverPacks({ localRoot: root });
53	  const { path, existed, declared } = seedDeclaration(root, packs);
54	  if (existed) {
55	    console.log(`${path} already exists — leaving it as-is.`);
56	    process.exit(0);
57	  }
58	  console.log(`Wrote ${path} (packs: ${declared.map(packEntryId).join(', ')}).`);
59	  // The adoption interview (surfacing each declared pack's pending questions) is
60	  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
61	  // by the SessionStart interview-check step — not printed here, so this runner
62	  // imports no pack.
63	  process.exit(0);
64	}
65	
66	const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
67	const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });
68	
69	// Settings/load integrity — pack-agnostic, so the world runner owns them.
70	// Settings validity is checked at load: malformed JSON, an unknown
71	// property, and a wrong pack name are all equally settings errors. loadConfig
72	// reports the first two; the runner adds unknown pack names (only it holds the
73	// registry) and broken/duplicate local pack.mjs faults.
74	const findings = [];
75	for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
76	for (const e of packErrors) findings.push(configError(e.what, e.fix));
77	// knownIds spans canon AND local packs, so a declared local pack id is valid and
78	// the unknown-pack message lists it among the declarable packs. ctx.config.packs
79	// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
80	// declaration already resolved through packEntryId.
81	const knownIds = new Set(packs.map((p) => p.id));
82	for (const name of ctx.config.packs) {
83	  if (typeof name === 'string' && !knownIds.has(name)) {
84	    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
85	  }
86	}
87	// (Adoption-interview hygiene is a skill-owned check that runs below with the
88	// other active-pack rules; a malformed `questions` field arrives as a load fault
89	// in packErrors above. Neither names a pack here.)
90	
91	// The world rules: everything not scoped to the work. A broken contributedRules
92	// seam is a config-level fault surfaced here (the world runner owns diagnostics).
93	findings.push(...runActivePackRules(ctx, packs, {
94	  includeRule: (rule) => rule.scope !== 'work',
95	  onContributeError: (pack, e) => findings.push(configError(
96	    `the "${pack.id}" pack's contributedRules failed: ${e.message}`, 'fix the pack manifest, or the contribution it interprets')),
97	}));
98	
99	const blocking = reportFindings(findings, ctx.config, { scopeLabel: 'world', mode: ctx.mode, baseRef: ctx.baseRef });
100	process.exit(blocking ? 1 : 0);
101

